using System.Net.Mail;
using System.Net.Mime;
using System.Text;
using Anything.Core.Content;
using Anything.Core.Content.Extract;

namespace Anything.Tests.Content.Readers;

public class MailReadersTests
{
    // ------------------------------------------------------------------ EML, generated by System.Net.Mail (an independent encoder)

    static byte[] Generate(Action<MailMessage> build)
    {
        var dir = Directory.CreateTempSubdirectory("rp-eml-");
        try
        {
            using (var client = new SmtpClient { DeliveryMethod = SmtpDeliveryMethod.SpecifiedPickupDirectory, PickupDirectoryLocation = dir.FullName })
            using (var message = new MailMessage())
            {
                build(message);
                client.Send(message);
            }
            return File.ReadAllBytes(Directory.GetFiles(dir.FullName, "*.eml").Single());
        }
        finally { dir.Delete(recursive: true); }
    }

    internal static byte[] GeneratedMessage() => Generate(m =>
    {
        m.From = new MailAddress("anna@example.com", "Anna Müller");
        m.To.Add(new MailAddress("bob@example.com", "Bøb Tester"));
        m.CC.Add(new MailAddress("carol@example.com", "Carol"));
        m.Subject = "Quarterly résumé 日本語 report";
        m.SubjectEncoding = Encoding.UTF8;
        m.Body = "Plain body with café and naïve words.\r\nSecond line.";
        m.BodyEncoding = Encoding.UTF8;
        m.BodyTransferEncoding = TransferEncoding.QuotedPrintable;
        m.AlternateViews.Add(AlternateView.CreateAlternateViewFromString("<html><body><p>html only words</p></body></html>", Encoding.UTF8, "text/html"));
        var attachment = new Attachment(new MemoryStream(Encoding.ASCII.GetBytes("attachment secret content")), "Rechnung März €.pdf", "application/pdf");
        attachment.NameEncoding = Encoding.UTF8;
        m.Attachments.Add(attachment);
    });

    [Fact]
    public void Generated_message_gives_fields_plain_body_and_attachment_names()
    {
        var doc = ReaderRun.Bytes(GeneratedMessage(), "eml");
        Assert.Equal(DocStatus.Ok, doc.Status);
        Assert.Equal("Quarterly résumé 日本語 report", doc.Field(DocField.Subject));
        Assert.Contains("Anna Müller", doc.Field(DocField.Sender));
        Assert.Contains("anna@example.com", doc.Field(DocField.Sender));
        Assert.Contains("Bøb Tester", doc.Field(DocField.Recipients));
        Assert.Contains("carol@example.com", doc.Field(DocField.Recipients));
        Assert.Contains("Plain body with café and naïve words.", doc.Body);
        Assert.Contains("Second line.", doc.Body);
        Assert.DoesNotContain("html only words", doc.Body); // plain text wins within the alternative
        Assert.Contains("Rechnung März €.pdf", doc.Body);
        Assert.DoesNotContain("secret", doc.Body); // attachment contents are never read
    }

    [Fact]
    public void Html_only_message_is_stripped_and_base64_decoded()
    {
        var bytes = Generate(m =>
        {
            m.From = new MailAddress("a@example.com");
            m.To.Add("b@example.com");
            m.Subject = "Html only";
            m.IsBodyHtml = true;
            m.Body = "<html><head><style>p{color:red}</style></head><body><p>Grüße &amp; <b>bold</b> words</p></body></html>";
            m.BodyEncoding = Encoding.UTF8;
            m.BodyTransferEncoding = TransferEncoding.Base64;
        });
        var doc = ReaderRun.Bytes(bytes, "eml");
        Assert.Equal("Grüße & bold words", doc.Body.Trim());
    }

    [Fact]
    public void Rfc2231_names_continuations_and_split_encoded_words_decode()
    {
        // "€" is E2 82 AC in UTF-8; the subject's encoded words split it between two words.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        string korean = Convert.ToBase64String(Encoding.GetEncoding(949).GetBytes("한국"));
        string eml = "From: =?utf-8?Q?J=C3=BCrgen?= <j@example.com>\r\n" +
            $"To: =?ks_c_5601-1987?B?{korean}?= <k@example.com>\r\n" +
            "Subject: =?UTF-8?B?4oI=?=\r\n =?UTF-8?B?rCBwcmljZQ==?= list\r\n" +
            "MIME-Version: 1.0\r\nContent-Type: multipart/mixed; boundary=\"b1\"\r\n\r\n" +
            "preamble\r\n--b1\r\nContent-Type: text/plain; charset=x-unknown-charset\r\nContent-Transfer-Encoding: quoted-printable\r\n\r\n" +
            "soft=\r\nbroken line and caf=C3=A9\r\n" +
            "--b1\r\nContent-Type: application/octet-stream\r\n" +
            "Content-Disposition: attachment; filename*0*=UTF-8''%E2%82%AC%20rates; filename*1=\" 2024.xlsx\"\r\n\r\nAAAA\r\n" +
            "--b1\r\nContent-Type: message/rfc822\r\n\r\nSubject: inner\r\nContent-Type: text/plain\r\n\r\nforwarded inner text\r\n" +
            "--b1--\r\nepilogue\r\n";
        var doc = ReaderRun.Bytes(Encoding.ASCII.GetBytes(eml), "eml");
        Assert.Equal("€ price list", doc.Field(DocField.Subject));
        Assert.Equal("Jürgen <j@example.com>", doc.Field(DocField.Sender));
        Assert.Equal("한국 <k@example.com>", doc.Field(DocField.Recipients));
        Assert.Contains("softbroken line and café", doc.Body);
        Assert.Contains("€ rates 2024.xlsx", doc.Body);
        Assert.Contains("forwarded inner text", doc.Body);
        Assert.DoesNotContain("preamble", doc.Body);
        Assert.DoesNotContain("epilogue", doc.Body);
    }

    [Fact]
    public void Header_decoding_helpers()
    {
        Assert.Equal("a b", EmlReader.DecodeWords("=?utf-8?q?a?= b"));
        Assert.Equal("ab", EmlReader.DecodeWords("=?utf-8?q?a?=  =?utf-8?q?b?="));
        Assert.Equal("plain =?bad", EmlReader.DecodeWords("plain =?bad"));
        Assert.Equal("Ab", EmlReader.DecodeWords("=?iso-8859-1*en?q?A?==?iso-8859-1?q?b?="));
        var (value, parameters) = EmlReader.Parameters("Text/Plain; Charset=\"utf-8\"; name*=iso-8859-1'de'K%E4se.txt; x=\"a;b\"");
        Assert.Equal("Text/Plain", value);
        Assert.Equal("utf-8", parameters["charset"]);
        Assert.Equal("Käse.txt", parameters["name"]);
        Assert.Equal("a;b", parameters["x"]);
        // Raw 8-bit headers: UTF-8 when valid.
        Assert.Equal("Grüße", EmlReader.DecodeHeader(Encoding.Latin1.GetString(Encoding.UTF8.GetBytes("Grüße"))));
    }

    [Fact]
    public void Deep_and_wide_mime_trees_are_bounded()
    {
        var sb = new StringBuilder("Subject: deep\r\nContent-Type: multipart/mixed; boundary=\"d0\"\r\n\r\n");
        for (int i = 0; i < 50; i++) sb.Append($"--d{i}\r\nContent-Type: multipart/mixed; boundary=\"d{i + 1}\"\r\n\r\n");
        sb.Append("--d50\r\nContent-Type: text/plain\r\n\r\ntoo deep words\r\n");
        var doc = ReaderRun.Bytes(Encoding.ASCII.GetBytes(sb.ToString()), "eml");
        Assert.Equal("deep", doc.Field(DocField.Subject));
        Assert.DoesNotContain("too deep words", doc.Body);

        var wide = new StringBuilder("Subject: wide\r\nContent-Type: multipart/mixed; boundary=\"w\"\r\n\r\n");
        for (int i = 0; i < 2000; i++) wide.Append($"--w\r\nContent-Type: text/plain\r\n\r\npart{i}\r\n");
        var many = ReaderRun.Bytes(Encoding.ASCII.GetBytes(wide.ToString()), "eml");
        Assert.Contains("part0", many.Body);
        Assert.DoesNotContain("part1999", many.Body);
        Assert.Equal(DocStatus.Truncated, many.Status); // the part cap left later parts unread

        // A message within the cap is read whole.
        var within = new StringBuilder("Subject: within\r\nContent-Type: multipart/mixed; boundary=\"w\"\r\n\r\n");
        for (int i = 0; i < 100; i++) within.Append($"--w\r\nContent-Type: text/plain\r\n\r\npart{i}\r\n");
        within.Append("--w--\r\n");
        var whole = ReaderRun.Bytes(Encoding.ASCII.GetBytes(within.ToString()), "eml");
        Assert.Equal(DocStatus.Ok, whole.Status);
        Assert.Contains("part99", whole.Body);
    }

    [Theory]
    [InlineData(1)]
    [InlineData(275)]
    public void Headers_full_of_unclosed_encoded_words_decode_in_linear_time(int headers)
    {
        string half = string.Concat(Enumerable.Repeat("=?a?B?", 10_000)); // 60,000 characters of candidates
        var sb = new StringBuilder("From: a@b.c\r\n");
        for (int i = 0; i < headers; i++) sb.Append(i < 100 ? "To: " : "Subject: ").Append(half).Append("\r\n ").Append(half).Append("\r\n");
        sb.Append("Subject: hello\r\n\r\nbody words\r\n");
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var doc = ReaderRun.Bytes(Encoding.ASCII.GetBytes(sb.ToString()), "eml");
        Assert.Equal("body words", doc.Body.Trim());
        Assert.True(sw.ElapsedMilliseconds < ExtractLimits.Local.MaxMilliseconds / 5, $"{sw.ElapsedMilliseconds} ms");
    }

    [Fact]
    public void Headers_full_of_words_in_unknown_charsets_decode_quickly()
    {
        var line = new StringBuilder();
        for (int i = 0; line.Length < 60_000; i++) line.Append("=?x").Append(i % 2).Append("?B?QQ==?= ");
        string half = line.ToString();
        var sb = new StringBuilder("From: a@b.c\r\n");
        for (int i = 0; i < 266; i++) sb.Append(i < 100 ? "To: " : "Subject: ").Append(half).Append("\r\n ").Append(half).Append("\r\n");
        sb.Append("\r\nbody words\r\n");
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var doc = ReaderRun.Bytes(Encoding.ASCII.GetBytes(sb.ToString()), "eml");
        Assert.StartsWith("AAAA", doc.Field(DocField.Subject)); // unknown charsets fall back, words still decoded
        Assert.True(sw.ElapsedMilliseconds < ExtractLimits.Local.MaxMilliseconds / 5, $"{sw.ElapsedMilliseconds} ms");
        // The budget is checked while a header decodes: a cancelled read stops there.
        using var cts = new CancellationTokenSource();
        var budget = new ExtractBudget(ExtractLimits.Local, cts.Token);
        cts.Cancel();
        Assert.Throws<OperationCanceledException>(() => EmlReader.DecodeHeader(half, budget));
    }

    [Fact]
    public void Header_decoding_keeps_its_rules_with_bounded_searches()
    {
        // A word right at the 1,024-character limit decodes; a longer one stays as it is.
        string payload = new('A', 1014);
        string word = $"=?utf-8?B?{payload}?=";
        Assert.Equal(1024, word.IndexOf("?=", 10, StringComparison.Ordinal)); // "?=" starts 1,024 characters in
        Assert.NotEqual(word, EmlReader.DecodeWords(word));
        string longer = $"=?utf-8?B?{payload}AAAA?=";
        Assert.Equal(longer, EmlReader.DecodeWords(longer));
        Assert.Equal("€ x", EmlReader.DecodeWords("=?utf-8?B?4oKs?= x"));
        Assert.Equal("Q", EmlReader.DecodeWords("=?utf-8?B?UQ?="));
    }

    // ------------------------------------------------------------------ CFB and MSG

    [Fact]
    public void Spec_example_compound_file_reads_stream_1()
    {
        var budget = new ExtractBudget(ExtractLimits.Local, CancellationToken.None);
        var cfb = CompoundFile.Open(new MemoryByteSource(CfbFixtures.SpecExample(), budget), budget);
        int storage = cfb.Find(cfb.Root, "storage 1");
        Assert.Equal(CompoundFile.EntryType.Storage, cfb.Type(storage));
        int stream = cfb.Find(storage, "Stream 1");
        Assert.Equal(544, cfb.Size(stream));
        var data = cfb.ReadStream(stream, 1 << 20)!;
        Assert.Equal(string.Concat(Enumerable.Repeat("Data for stream 1", 32)), Encoding.ASCII.GetString(data));
    }

    [Fact]
    public void Compound_file_loops_and_bad_headers_are_contained()
    {
        var budget = new ExtractBudget(ExtractLimits.Local, CancellationToken.None);
        // A FAT loop in the directory's own chain (sector 1 → 1). The directory is read with no declared length (up to
        // 16 MB), so only the visited set ends it: without it, sector 1 would be read 32,768 times into 131,072 entries.
        var directoryLoop = CfbFixtures.SpecExample();
        BitConverter.GetBytes(1u).CopyTo(directoryLoop, 0x204);
        var counted = new CountingSource(directoryLoop, budget);
        var looped = CompoundFile.Open(counted, budget);
        Assert.Equal(4, looped.EntryCount); // the one sector there is
        Assert.True(counted.BytesRead < 8 << 10, $"read {counted.BytesRead} bytes");
        string expected = string.Concat(Enumerable.Repeat("Data for stream 1", 32));
        Assert.Equal(expected, Encoding.ASCII.GetString(looped.ReadStream(looped.Find(looped.Find(looped.Root, "Storage 1"), "Stream 1"), 1 << 20)!));

        // A FAT loop in the mini stream's container chain (sector 4 → 3) while the root entry declares 8 sectors, longer
        // than the cycle: the chain stops at the cycle and the stream inside it still reads.
        var loop = CfbFixtures.SpecExample();
        BitConverter.GetBytes(3u).CopyTo(loop, 0x210);
        BitConverter.GetBytes(0x1000u).CopyTo(loop, 0x478);
        var cfb = CompoundFile.Open(new MemoryByteSource(loop, budget), budget);
        Assert.Equal(expected, Encoding.ASCII.GetString(cfb.ReadStream(cfb.Find(cfb.Find(cfb.Root, "Storage 1"), "Stream 1"), 1 << 20)!));
        // A directory cycle: Stream 1's right sibling is Storage 1, whose child is Stream 1.
        var cycle = CfbFixtures.SpecExample();
        BitConverter.GetBytes(1u).CopyTo(cycle, 0x548);
        BitConverter.GetBytes(2u).CopyTo(cycle, 0x4C4);
        var c = CompoundFile.Open(new MemoryByteSource(cycle, budget), budget);
        Assert.True(c.Children(1).Count <= 3);
        // Sector shifts other than 9/12 and 6.
        var shift = CfbFixtures.SpecExample();
        shift[0x1E] = 10;
        Assert.Throws<InvalidDataException>(() => CompoundFile.Open(new MemoryByteSource(shift, budget), budget));
        var mini = CfbFixtures.SpecExample();
        mini[0x20] = 7;
        Assert.Equal(DocStatus.Damaged, ReaderRun.Bytes(mini, "msg").Status);
    }

    /// <summary>MS-OXRTFCP 3.1.1: "{\rtf1\ansi\ansicpg1252\pard hello world}\r\n" compressed.</summary>
    internal static readonly byte[] CompressedRtfExample = Convert.FromHexString(
        "2d0000002b0000004c5a4675f1c5c7a7" +
        "03000a007263706731323542320af320" +
        "68656c0900206277" + "05b06c647d0a800f" +
        "a0");

    [Fact]
    public void Compressed_rtf_worked_example_decompresses()
    {
        var rtf = CompressedRtf.Decompress(CompressedRtfExample, 1 << 20);
        Assert.Equal("{\\rtf1\\ansi\\ansicpg1252\\pard hello world}\r\n", Encoding.ASCII.GetString(rtf!));
        Assert.Equal(0xA7C7C5F1u, CompressedRtf.Crc(CompressedRtfExample.AsSpan(16)));
    }

    internal static byte[] Msg(bool compressedRtf = false, bool cyrillic = false) => CfbFixtures.Ole(root =>
    {
        CfbFixtures.Properties(root, 32, (0x3FFD, cyrillic ? 1251 : 1252), (0x3FDE, 65001));
        if (cyrillic) CfbFixtures.String8(root, 0x0037, "Отчёт за квартал", 1251);
        else CfbFixtures.Unicode(root, 0x0037, "Quarterly résumé report");
        CfbFixtures.Unicode(root, 0x0C1A, "Anna Sender");
        CfbFixtures.Unicode(root, 0x5D01, "anna@example.com");
        CfbFixtures.Unicode(root, 0x0E04, "Bob Receiver");
        CfbFixtures.Unicode(root, 0x0E03, "Carol Copy");
        if (compressedRtf) CfbFixtures.Stream(root, "__substg1.0_10090102", CompressedRtfExample);
        else CfbFixtures.Unicode(root, 0x1000, "Body words café. " + new string('x', 6000) + " tail words");
        var recipient = CfbFixtures.Storage(root, "__recip_version1.0_#00000000");
        CfbFixtures.Properties(recipient, 8);
        CfbFixtures.Unicode(recipient, 0x3001, "Bob Receiver");
        CfbFixtures.Close(recipient);
        var attachment = CfbFixtures.Storage(root, "__attach_version1.0_#00000000");
        CfbFixtures.Properties(attachment, 8, (0x3705, 1));
        CfbFixtures.Unicode(attachment, 0x3707, "Angebot 2024.pdf");
        CfbFixtures.Stream(attachment, "__substg1.0_37010102", Encoding.ASCII.GetBytes("attachment secret bytes"));
        CfbFixtures.Close(attachment);
    });

    [Fact]
    public void Msg_from_ole_storage_gives_fields_body_and_attachment_names()
    {
        var doc = ReaderRun.Bytes(Msg(), "msg");
        Assert.Equal(DocStatus.Ok, doc.Status);
        Assert.Equal("Quarterly résumé report", doc.Field(DocField.Subject));
        Assert.Equal("Anna Sender <anna@example.com>", doc.Field(DocField.Sender));
        Assert.Equal("Bob Receiver; Carol Copy", doc.Field(DocField.Recipients));
        Assert.StartsWith("Body words café.", doc.Body);
        Assert.Contains("tail words", doc.Body); // a stream over the 4,096-byte cutoff, through the FAT
        Assert.Contains("Angebot 2024.pdf", doc.Body);
        Assert.DoesNotContain("secret", doc.Body);
    }

    [Fact]
    public void Msg_without_display_lists_keeps_every_recipient()
    {
        var msg = CfbFixtures.Ole(root =>
        {
            CfbFixtures.Properties(root, 32, (0x3FFD, 1252));
            CfbFixtures.Unicode(root, 0x0037, "Three recipients");
            CfbFixtures.Unicode(root, 0x1000, "Body words");
            foreach (var (i, name) in new[] { (0, "Bob Receiver"), (1, "Carol Copy"), (2, "Dave Third") })
            {
                var recipient = CfbFixtures.Storage(root, $"__recip_version1.0_#{i:X8}");
                CfbFixtures.Properties(recipient, 8);
                CfbFixtures.Unicode(recipient, 0x3001, name);
                CfbFixtures.Close(recipient);
            }
        });
        var doc = ReaderRun.Bytes(msg, "msg");
        Assert.Equal(DocStatus.Ok, doc.Status);
        var recipients = doc.Field(DocField.Recipients)!.Split("; ");
        Assert.Equal(["Bob Receiver", "Carol Copy", "Dave Third"], recipients.Order());
    }

    [Fact]
    public void Msg_8bit_strings_use_the_message_code_page_and_compressed_rtf_is_read()
    {
        var cyrillic = ReaderRun.Bytes(Msg(cyrillic: true), "msg");
        Assert.Equal("Отчёт за квартал", cyrillic.Field(DocField.Subject));
        var rtf = ReaderRun.Bytes(Msg(compressedRtf: true), "msg");
        Assert.Equal("hello world", rtf.Body.Split('\n')[0].Trim());
    }
}
